cat > /app/output/styles.css <<'EOF'
:root {
  --bg: #101321;
  --panel: #151a2d;
  --panel-2: #1b2138;
  --panel-3: #232b45;
  --text: #e8ecff;
  --muted: #9ba7c7;
  --brand: #2962ff;
  --brand-2: #16b3b3;
  --gain: #2dd881;
  --loss: #f7525f;
  --border: #2a3354;
}
* { box-sizing: border-box; }
html,body { margin:0; font-family: Inter, "DM Sans", Arial, sans-serif; background: var(--bg); color: var(--text); }
a { color: inherit; text-decoration: none; }
.app { min-height:100vh; }
.topbar { display:flex; align-items:center; justify-content:space-between; padding:12px 16px; border-bottom:1px solid var(--border); background:#0f1220; position:sticky; top:0; z-index:20; }
.brand { display:flex; align-items:center; gap:10px; font-weight:700; }
.logo { width:28px; height:28px; border-radius:8px; background:linear-gradient(135deg,var(--brand),var(--brand-2)); }
.nav { display:flex; gap:8px; flex-wrap:wrap; }
.nav a { padding:8px 12px; border-radius:8px; color:var(--muted); background:transparent; }
.nav a.active, .nav a:hover { background:var(--panel); color:var(--text); }
.cta { background:var(--brand); padding:8px 12px; border-radius:8px; font-weight:600; }
.container { padding:16px; }
.grid { display:grid; gap:12px; }
.grid-2 { grid-template-columns:2fr 1fr; }
.grid-3 { grid-template-columns:repeat(3,1fr); }
.card { background:var(--panel); border:1px solid var(--border); border-radius:12px; padding:12px; }
.card h3 { margin:0 0 10px; font-size:14px; color:#cdd6f6; text-transform:uppercase; letter-spacing:.03em; }
.hero h1 { font-size:34px; margin:6px 0 10px; }
.hero p { color:var(--muted); max-width:780px; }
.row { display:flex; align-items:center; justify-content:space-between; gap:8px; }
.badge { padding:2px 8px; border-radius:999px; font-size:12px; font-weight:700; }
.gain { color:var(--gain); }
.loss { color:var(--loss); }
.badge.gain { background:rgba(45,216,129,.14); }
.badge.loss { background:rgba(247,82,95,.14); }
.table { width:100%; border-collapse:collapse; font-size:13px; }
.table th, .table td { padding:8px 6px; border-bottom:1px solid #232b46; text-align:left; }
.table th { color:var(--muted); font-weight:600; font-size:12px; }
.tabs { display:flex; gap:8px; flex-wrap:wrap; margin-bottom:10px; }
.tab-btn { padding:6px 10px; border:1px solid var(--border); border-radius:8px; color:var(--muted); background:var(--panel-2); cursor:pointer; }
.tab-btn.active { color:var(--text); border-color:var(--brand); background:rgba(41,98,255,.18); }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.kpis { display:grid; grid-template-columns:repeat(4,1fr); gap:10px; }
.kpi { background:var(--panel-2); border:1px solid var(--border); border-radius:10px; padding:10px; }
.spark { height:28px; border-radius:6px; background:linear-gradient(180deg,rgba(41,98,255,.35),rgba(41,98,255,0)); position:relative; overflow:hidden; }
.spark:before { content:""; position:absolute; inset:8px 5px auto 5px; height:2px; background:linear-gradient(90deg,#3ec6ff,#2dd881,#f7a35c); transform:skewX(-15deg); }
.layout-chart { display:grid; grid-template-columns:280px 1fr 320px; gap:12px; }
.watch-group { margin-bottom:8px; border:1px solid var(--border); border-radius:10px; overflow:hidden; }
.watch-header { width:100%; text-align:left; background:var(--panel-2); color:var(--text); border:0; padding:8px 10px; cursor:pointer; font-weight:600; }
.watch-content { display:none; }
.watch-content.open { display:block; }
.chart-box { height:420px; background:radial-gradient(circle at 20% 10%, #213663 0%, #12172a 40%); border:1px solid var(--border); border-radius:12px; padding:10px; position:relative; }
.candles { position:absolute; inset:40px 12px 16px 12px; background:repeating-linear-gradient(to right, transparent 0 22px, rgba(255,255,255,.03) 22px 23px), repeating-linear-gradient(to bottom, transparent 0 42px, rgba(255,255,255,.03) 42px 43px); border-radius:8px; }
.toolbar { display:flex; gap:6px; flex-wrap:wrap; }
.tool { background:var(--panel-2); border:1px solid var(--border); border-radius:8px; padding:5px 8px; font-size:12px; color:#d3dcff; }
.footer-note { color:var(--muted); font-size:12px; margin-top:8px; }
.broker-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:12px; }
.broker-card { background:var(--panel); border:1px solid var(--border); border-radius:12px; padding:12px; }
.offer { background:rgba(22,179,179,.15); color:#6af0f0; border-radius:8px; padding:6px; font-size:12px; margin-top:8px; }
@media (max-width: 1100px){ .layout-chart{ grid-template-columns:1fr; } .grid-2,.grid-3,.broker-grid,.kpis{ grid-template-columns:1fr; } }
EOF

cat > /app/output/app.js <<'EOF'
document.querySelectorAll('[data-tabs]').forEach((tabsWrap) => {
  const buttons = tabsWrap.querySelectorAll('[data-tab-target]');
  const panels = tabsWrap.querySelectorAll('[data-tab-panel]');
  buttons.forEach((btn) => {
    btn.addEventListener('click', () => {
      buttons.forEach(b => b.classList.remove('active'));
      panels.forEach(p => p.classList.remove('active'));
      btn.classList.add('active');
      const target = tabsWrap.querySelector(`[data-tab-panel="${btn.dataset.tabTarget}"]`);
      if (target) target.classList.add('active');
    });
  });
});

document.querySelectorAll('.watch-header').forEach((header) => {
  header.addEventListener('click', () => {
    const panel = header.nextElementSibling;
    panel.classList.toggle('open');
  });
});
EOF

